  const atmosphere=new THREE.Mesh(new THREE.SphereGeometry(2.65,48,32),new THREE.ShaderMaterial({transparent:true,depthWrite:false,side:THREE.BackSide,blending:THREE.AdditiveBlending,vertexShader:'varying vec3 vn; varying vec3 vp; void main(){vn=normalize(normalMatrix*normal);vec4 p=modelViewMatrix*vec4(position,1.0);vp=p.xyz;gl_Position=projectionMatrix*p;}',fragmentShader:'varying vec3 vn;varying vec3 vp;void main(){float f=pow(1.0-abs(dot(normalize(vn),normalize(-vp))),3.0);gl_FragColor=vec4(0.15,0.65,1.0,f*0.65);}' }));earthGroup.add(atmosphere);
  for(const radius of [3.2,4.5]){const orbit=ring(radius,0x59dce5,.17);orbit.rotation.z=.3;earthGroup.add(orbit);}
  const latitude=ring(2.58,0x59dce5,.12);earthGroup.add(latitude);const meridian=ring(2.58,0x59dce5,.12);meridian.rotation.x=Math.PI/2;earthGroup.add(meridian);
  const planetGroup=worldGroups.get('planetary'),mars=new THREE.Mesh(new THREE.SphereGeometry(1.65,48,32),new THREE.MeshPhongMaterial({map:sphereTexture(),shininess:5}));mars.userData.zone='planetary';planetGroup.add(mars);const moon=new THREE.Mesh(new THREE.SphereGeometry(.35,20,16),new THREE.MeshPhongMaterial({color:0xa0a8b0}));moon.position.set(3,1,.6);planetGroup.add(moon);for(const r of [2.8,4.1])planetGroup.add(ring(r,0xf1ae75,.19));
  const inter=worldGroups.get('interstellar');const starPositions=[];for(let i=0;i<12;i++){const p=new THREE.Vector3((rand()-.5)*7,(rand()-.5)*4,(rand()-.5)*5);starPositions.push(p);const dot=new THREE.Sprite(new THREE.SpriteMaterial({map:texture,color:i%3?0x83c9ff:0xffe3b7,transparent:true,blending:THREE.AdditiveBlending,depthWrite:false}));dot.position.copy(p);dot.scale.setScalar(.5+rand()*.5);inter.add(dot);}for(let i=1;i<12;i++)inter.add(line([starPositions[i-1].toArray(),starPositions[i].toArray()],0x579bdf,.12));
  function galaxy(group,size,count=1300){const positions=[],cs=[];for(let i=0;i<count;i++){const rad=Math.pow(rand(),.6)*size,arm=i%4,angle=rad*.6+arm*Math.PI/2+(rand()-.5)*(.45+rad*.03),col=new THREE.Color().setHSL(.61+rand()*.12,.45,.45+(.5-rad/size*.35));positions.push(Math.cos(angle)*rad,(rand()-.5)*.3,Math.sin(angle)*rad);cs.push(col.r,col.g,col.b);}const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));g.setAttribute('color',new THREE.Float32BufferAttribute(cs,3));group.add(new THREE.Points(g,new THREE.PointsMaterial({map:texture,size:.15,vertexColors:true,transparent:true,depthWrite:false,blending:THREE.AdditiveBlending})));const core=new THREE.Sprite(new THREE.SpriteMaterial({map:texture,color:0xffd0df,transparent:true,depthWrite:false,blending:THREE.AdditiveBlending}));core.scale.setScalar(size*.85);group.add(core);}
  const galactic=worldGroups.get('galactic');galaxy(galactic,5);galactic.rotation.x=.34;galactic.rotation.z=-.25;
  const cosmic=worldGroups.get('cosmic'),cluster=[];for(let i=0;i<24;i++){const p=new THREE.Vector3((rand()-.5)*13,(rand()-.5)*7,(rand()-.5)*9);cluster.push(p);const dot=new THREE.Sprite(new THREE.SpriteMaterial({map:texture,color:i%2?0xf3aac9:0xa198ef,transparent:true,depthWrite:false,blending:THREE.AdditiveBlending}));dot.position.copy(p);dot.scale.setScalar(.7+rand()*.7);cosmic.add(dot);}for(let i=0;i<cluster.length;i++){const neighbors=cluster.map((p,j)=>({j,d:p.distanceToSquared(cluster[i])})).filter(p=>p.j!==i).sort((a,b)=>a.d-b.d).slice(0,3);for(const n of neighbors)if(n.j>i)cosmic.add(line([cluster[i].toArray(),cluster[n.j].toArray()],0x916fa3,.22));}
  const abstract=worldGroups.get('abstract'),knot=new THREE.LineSegments(new THREE.EdgesGeometry(new THREE.TorusKnotGeometry(1.8,.32,90,9,2,3)),new THREE.LineBasicMaterial({color:0x92e9bf,transparent:true,opacity:.55}));abstract.add(knot);abstract.add(ring(3.8,0x92e9bf,.15));
  for(let i=0;i<ZONES.length-2;i++){const a=new THREE.Vector3(...ZONES[i].center),b=new THREE.Vector3(...ZONES[i+1].center),m=a.clone().lerp(b,.5);m.y+=3;const curve=new THREE.QuadraticBezierCurve3(a,m,b);scene.add(line(curve.getPoints(80).map(p=>p.toArray()),0x69a6ba,.13));}
  const nodeGeometry=new THREE.SphereGeometry(.072,8,6);
  for(const zone of ZONES){const records=works.filter(w=>spatialById.get(w.id)?.primary===zone.id).sort((a,b)=>(a.sort_year??a.first_year)-(b.sort_year??b.first_year));records.forEach((w,i)=>{const angle=i*Math.PI*2/Math.max(records.length,1)-Math.PI/2,r=(zone.id==='earth'?3.6:zone.id==='cosmic'?6.8:zone.id==='galactic'?5.8:3.4)+(i%3)*.28,y=Math.sin(i*2.39)*1.1;const mesh=new THREE.Mesh(nodeGeometry,new THREE.MeshBasicMaterial({color:zone.color}));mesh.position.set(Math.cos(angle)*r,y,Math.sin(angle)*r*.68);mesh.userData={work:w,zone:zone.id};const halo=new THREE.Sprite(new THREE.SpriteMaterial({map:texture,color:zone.color,transparent:true,opacity:.8,depthWrite:false,blending:THREE.AdditiveBlending}));halo.scale.setScalar(.45);mesh.add(halo);worldGroups.get(zone.id).add(mesh);nodeMeshes.push(mesh);});}
  const raycaster=new THREE.Raycaster(),pointer=new THREE.Vector2(),points=new Map();let pinchDistance=0;
  function hit(e){const rect=renderArea.getBoundingClientRect();pointer.set((e.clientX-rect.left)/rect.width*2-1,-((e.clientY-rect.top)/rect.height*2-1));raycaster.setFromCamera(pointer,camera);const hit=raycaster.intersectObjects([...nodeMeshes.filter(m=>m.visible),earth,mars],false)[0];return hit?.object;}
  function clearHover(){hovered=null;hover.hidden=true;renderArea.style.cursor='grab';}
  listen(renderArea,'pointerdown',e=>{renderArea.setPointerCapture(e.pointerId);points.set(e.pointerId,[e.clientX,e.clientY]);drag={x:e.clientX,y:e.clientY,startX:e.clientX,startY:e.clientY,moved:false};clearHover();});
  listen(renderArea,'pointermove',e=>{if(points.has(e.pointerId))points.set(e.pointerId,[e.clientX,e.clientY]);if(points.size===2){const [a,b]=[...points.values()],distance=Math.hypot(a[0]-b[0],a[1]-b[1]);if(pinchDistance>0)targetRadius=THREE.MathUtils.clamp(targetRadius*pinchDistance/distance,5,90);pinchDistance=distance;if(drag)drag.moved=true;return;}pinchDistance=0;if(drag&&points.size===1){yaw-=(e.clientX-drag.x)*.006;pitch=THREE.MathUtils.clamp(pitch+(e.clientY-drag.y)*.005,-1.1,1.1);drag.moved ||= Math.hypot(e.clientX-drag.startX,e.clientY-drag.startY)>5;drag.x=e.clientX;drag.y=e.clientY;return;}const object=hit(e);if(object?.userData.work){hovered=object;const w=object.userData.work;hover.innerHTML=`<span>${escapeHTML(w.year_display)} / ${escapeHTML(byZone.get(object.userData.zone).name)}</span><strong>${escapeHTML(w.title_zh)}</strong><small>点击打开作品分析 ↗</small>`;const rect=stage.getBoundingClientRect();hover.style.left=`${Math.min(e.clientX-rect.left+18,rect.width-225)}px`;hover.style.top=`${Math.max(15,e.clientY-rect.top-75)}px`;hover.hidden=false;renderArea.style.cursor='pointer';}else clearHover();});
  listen(renderArea,'pointerup',e=>{const wasClick=drag&&!drag.moved&&points.size===1;points.delete(e.pointerId);if(wasClick){const obj=hit(e);if(obj?.userData.work)onWork(obj.userData.work.id);else if(obj?.userData.zone)goZone(obj.userData.zone);}if(!points.size)drag=null;pinchDistance=0;});listen(renderArea,'pointercancel',()=>{points.clear();drag=null;pinchDistance=0;});listen(renderArea,'pointerleave',clearHover);
